/**
 * Active Water Events card — v2.
 *
 * Design source: Figma nodes, fetched one variant at a time
 *   198209:67180  Property 1=Default  — header + 5-column events table
 *   198209:67182  Property 1=empty    — "No active water events"
 *
 * Figma documents this node as shadcn `card`, with `toggle-group` / `toggle`
 * for Active|History, `badge` for the Ignored chip and the round type chip, and
 * `table-cell` for the grid cells. Those primitives are used here; the table
 * itself is a CSS grid because the project has no ui/table.
 *
 * The var(...) class names are copied from Figma untouched. Each one carries
 * its own literal fallback (`px-[var(--component/badge/px,8px)]`), so the design
 * value renders whether or not the project defines the token. Do not "simplify"
 * them into px-2 / text-slate-600 — that is how the previous pass lost fidelity.
 *
 * CARE: those class names contain a real backslash (`--colors\/slate\/400`).
 * They may only ever appear inside a JSX attribute string. In a JS string
 * literal the backslash is eaten at runtime while Tailwind still scans the
 * escaped source text, so the emitted class and the generated CSS stop
 * matching and the rule silently does nothing. That is why the long class
 * strings below are repeated inline instead of hoisted into constants.
 *
 * Assets: the Figma export URLs expire in ~7 days, so every glyph below is
 * inlined. The 3-wave Phosphor glyph is already owned by the project
 * (src/v2/icons/Waves — its 21-unit viewBox is the 14-unit export scaled 1.5x,
 * stroke included), and the five valve states are ValveStatus.jsx. Only the
 * 2-wave glyph, the location dot, the cell hairline and the empty-state
 * illustration were not already here.
 */

import { Fragment, useState } from 'react'
import { Badge } from '@/components/ui/badge'
import { Card } from '@/components/ui/card'
import { Separator } from '@/components/ui/separator'
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'
import { Waves } from '@/v2/icons'
import ValveStatus from './ValveStatus'

// ── Inlined Figma assets ───────────────────────────────────────────────────

/** Location Dot, 27px. Three concentric circles, outer two at 10% opacity.
 *  The Default variant ships it red (#FB2C36) and the empty variant slate
 *  (#90A1B9) — same geometry, different tint — so the fills are currentColor
 *  and the caller sets the colour. */
const LocationDot = (props) => (
  <svg viewBox="0 0 27 27" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" {...props}>
    <circle opacity="0.1" cx="13.5" cy="13.5" r="8.52632" fill="currentColor" />
    <circle opacity="0.1" cx="13.5" cy="13.5" r="13.5" fill="currentColor" />
    <circle cx="13.5" cy="13.5" r="2.84211" fill="currentColor" />
  </svg>
)

/** Phosphor "waves" with only TWO traces — a genuinely different export from
 *  the three-trace glyph in @/v2/icons, not a crop of it. The design uses it
 *  for the low-flow rows (stroke 0.874792 on a 14 viewBox, vs 0.720417 for the
 *  three-trace one). Recoloured to currentColor to match its sibling. */
const WavesLow = ({ size = 14, ...props }) => (
  <svg width={size} height={size} viewBox="0 0 14 14" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" {...props}>
    <g clipPath="url(#awe_waves_low)">
      <path d="M2.1875 10.1505C6.125 6.88625 7.875 13.2388 11.8125 9.97445" stroke="currentColor" strokeWidth="0.874792" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M2.1875 7.08805C6.125 3.82375 7.875 10.1762 11.8125 6.91195" stroke="currentColor" strokeWidth="0.874792" strokeLinecap="round" strokeLinejoin="round" />
    </g>
    <defs>
      <clipPath id="awe_waves_low"><rect width="14" height="14" fill="white" /></clipPath>
    </defs>
  </svg>
)

/** "Line 1" — a 12x1 rule that Figma rotates 90deg to divide location from
 *  address. Kept as the exported asset inside Figma's own rotate wrapper. */
const CellHairline = () => (
  <div className="flex h-[12px] items-center justify-center relative shrink-0 w-0">
    <div className="flex-none rotate-90">
      <div className="h-0 relative w-[12px]">
        <div className="absolute inset-[-1px_0_0_0]">
          <svg viewBox="0 0 12 1" fill="none" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="none" className="block max-w-none size-full" aria-hidden="true">
            <line y1="0.5" x2="12" y2="0.5" stroke="#90A1B9" />
          </svg>
        </div>
      </div>
    </div>
  </div>
)

/** Empty-state illustration (Figma 198424:62492, a raster export). Inlined as
 *  a data URI because the Figma URL expires; downsampled from 1448x1086 to
 *  432x324, still 3x the 144x108 box it renders into. */
const EMPTY_ILLUSTRATION = 'data:image/png;base64,'

// ── Event type table ───────────────────────────────────────────────────────
// `type` strings match src/data/events.js so a real CURRENT_EVENTS slice drops
// straight in. High flow gets the three-trace glyph, low flow the two-trace
// one — two separate exports, not one glyph scaled.
const SLATE_INK = '#90A1B9'
const TYPES = {
  'leak-high': { Glyph: Waves,    label: 'High flow' },
  'leak-low':  { Glyph: WavesLow, label: 'Low flow' },
}

// ── Mock data ──────────────────────────────────────────────────────────────
// Row-for-row the six rows of Figma 198209:67180, with the same addresses,
// chips, valve states and timestamp. The design leaves three system names as
// the literal placeholder "Cell contents"; those are filled in from the
// project's system vocabulary (src/data/systems.js) so the card reads as a
// card. Two resolved events exist so the History toggle has something to show.
const MOCK_EVENTS = [
  { id: 'awe-1', systemName: 'Booster Pump 12',     location: '360 Magnolia Row', address: '352 Palmer Road, Ware MA 1082',          type: 'leak-high', valve: 'open',     detectedAt: 'Apr 02, 2026 08:13:15', notifiedBy: 'CN', ignored: true,  resolved: false },
  { id: 'awe-2', systemName: 'System name',         location: 'Location',         address: '36 Paramount Drive, Raynham MA 2767',    type: 'leak-low',  valve: 'no-valve', detectedAt: 'Apr 02, 2026 08:13:15', notifiedBy: 'CN', ignored: false, resolved: false },
  { id: 'awe-3', systemName: 'Server Hall Cooling', location: 'Azure Amsterdam',  address: '425 Route 31, Macedon NY 14502',         type: 'leak-high', valve: 'error',    detectedAt: 'Apr 02, 2026 08:13:15', notifiedBy: 'CN', ignored: false, resolved: false },
  { id: 'awe-4', systemName: 'Sump Pump B1',        location: 'Parking Level B1', address: '1400 County Rd 64, Horseheads NY 14845', type: 'leak-low',  valve: 'closed',   detectedAt: 'Apr 02, 2026 08:13:15', notifiedBy: 'CN', ignored: false, resolved: false },
  { id: 'awe-5', systemName: 'Cooling Tower #1',    location: 'Tower One',        address: 'Manchester M1 2AB',                      type: 'leak-high', valve: 'open',     detectedAt: 'Apr 02, 2026 08:13:15', notifiedBy: 'CN', ignored: false, resolved: false },
  { id: 'awe-6', systemName: 'Fire Riser 2',        location: '360 Magnolia Row', address: '',                                       type: 'leak-high', valve: null,       detectedAt: 'Apr 02, 2026 08:13:15', notifiedBy: 'CN', ignored: false, resolved: false },
  { id: 'awe-7', systemName: 'Cooling Tower T2',    location: 'Terminal 2',       address: 'Heathrow Airport, London TW6',           type: 'leak-low',  valve: 'open',     detectedAt: 'Mar 28, 2026 14:02:40', notifiedBy: 'TM', ignored: false, resolved: true },
  { id: 'awe-8', systemName: 'Chiller Loop 4',      location: 'Plant Room',       address: '18 Dock Street, Leeds LS1 1UB',          type: 'leak-high', valve: 'closed',   detectedAt: 'Mar 27, 2026 09:48:02', notifiedBy: 'PS', ignored: false, resolved: true },
]

// ── Cells ──────────────────────────────────────────────────────────────────

function SystemCell({ event }) {
  return (
    <div className="content-stretch flex flex-[1_0_0] items-center min-w-px overflow-clip relative">
      <div className="content-stretch flex flex-col gap-[5px] items-start justify-center relative shrink-0">
        <div className="content-stretch flex gap-[5px] items-start relative shrink-0">
          {event.ignored ? (
            /* Figma "Badge", Type=Secondary — the ignored chip. */
            <Badge
              variant="secondary"
              className="bg-[var(--colors\/slate\/100,#f1f5f9)] border-[length:var(--component\/badge\/border-width,1px)] border-[var(--colors\/slate\/200,#e2e8f0)] border-solid content-stretch flex gap-[var(--component\/badge\/gap,4px)] h-[20px] items-center justify-center overflow-clip px-[var(--component\/badge\/px,8px)] py-[var(--component\/badge\/py,2px)] relative rounded-[var(--component\/badge\/radius,26px)] shrink-0 font-medium leading-[var(--text\/xs\/lh,16px)] text-[12px] text-[color:var(--colors\/slate\/400,#90a1b9)] whitespace-nowrap"
            >
              Ignored
            </Badge>
          ) : null}
          {event.ignored ? (
            <p className="[word-break:break-word] font-semibold leading-[var(--text\/sm\/lh,20px)] relative shrink-0 text-[color:var(--colors\/slate\/400,#90a1b9)] text-[length:var(--text\/sm\/size,14px)] whitespace-nowrap">
              {event.systemName}
            </p>
          ) : (
            <p className="[word-break:break-word] font-semibold leading-[var(--text\/sm\/lh,20px)] relative shrink-0 text-[color:var(--colors\/slate\/900,#0f172b)] text-[length:var(--text\/sm\/size,14px)] whitespace-nowrap">
              {event.systemName}
            </p>
          )}
        </div>

        <div className="content-stretch flex gap-[5px] items-center relative shrink-0">
          <p className="[word-break:break-word] font-normal leading-[var(--text\/xs\/lh-snug,16.5px)] relative shrink-0 text-[color:var(--colors\/slate\/500,#62748e)] text-[length:var(--text\/xs\/size,12px)] whitespace-nowrap">
            {event.location}
          </p>
          {event.address ? <CellHairline /> : null}
          {event.address ? (
            <p className="[word-break:break-word] font-normal leading-[var(--text\/xs\/lh-snug,16.5px)] relative shrink-0 text-[color:var(--colors\/slate\/500,#62748e)] text-[length:var(--text\/xs\/size,12px)] whitespace-nowrap">
              {event.address}
            </p>
          ) : null}
        </div>
      </div>
    </div>
  )
}

/** The round 22px type chip. Fill and glyph ink move together on every row of
 *  the design, and an ignored event dims the pair to slate. The three tones are
 *  spelled out as whole class strings rather than composed, so each stays a
 *  JSX attribute and keeps Figma's exact token + fallback (see the CARE note at
 *  the top of the file). Glyph inks are the literal strokes the SVGs ship. */
function TypeCell({ event }) {
  const type = TYPES[event.type] ?? TYPES['leak-high']
  const Glyph = type.Glyph

  // The two-trace glyph sits in an 18px leftIcon frame with 4px of bottom
  // padding, which optically centres two waves where three would sit.
  const glyph =
    event.type === 'leak-low' ? (
      <span className="content-stretch flex flex-col items-start pb-[4px] relative shrink-0">
        <Glyph size={14} />
      </span>
    ) : (
      <span className="content-stretch flex flex-col items-start relative shrink-0">
        <Glyph size={14} />
      </span>
    )

  return (
    <div className="content-stretch flex flex-[1_0_0] gap-[var(--spacing\/1\,5,6px)] h-full items-center min-w-px overflow-clip relative">
      {/* Figma "Badge" used as a 22px round chip — no border in the design. */}
      {event.ignored ? (
        <Badge variant="secondary" title={type.label} className="bg-[var(--colors\/slate\/200,#e2e8f0)] border-0 content-stretch flex flex-col gap-[var(--component\/badge\/gap,4px)] items-center justify-center overflow-clip px-[var(--component\/badge\/px,8px)] py-[var(--component\/badge\/py,2px)] relative rounded-[var(--component\/pro\/application\/inline-hint\/rail\/radius,26px)] shrink-0 size-[22px] text-[#90A1B9]">
          {glyph}
        </Badge>
      ) : event.type === 'leak-low' ? (
        <Badge variant="secondary" title={type.label} className="bg-[var(--colors\/orange\/100,#ffedd4)] border-0 content-stretch flex flex-col gap-[var(--component\/badge\/gap,4px)] items-center justify-center overflow-clip px-[var(--component\/badge\/px,8px)] py-[var(--component\/badge\/py,2px)] relative rounded-[var(--component\/pro\/application\/inline-hint\/rail\/radius,26px)] shrink-0 size-[22px] text-[#FF6900]">
          {glyph}
        </Badge>
      ) : (
        <Badge variant="secondary" title={type.label} className="bg-[var(--colors\/red\/100,#ffe2e2)] border-0 content-stretch flex flex-col gap-[var(--component\/badge\/gap,4px)] items-center justify-center overflow-clip px-[var(--component\/badge\/px,8px)] py-[var(--component\/badge\/py,2px)] relative rounded-[var(--component\/pro\/application\/inline-hint\/rail\/radius,26px)] shrink-0 size-[22px] text-[#FB2C36]">
          {glyph}
        </Badge>
      )}
    </div>
  )
}

function ValveCell({ event }) {
  return (
    <div className="content-stretch flex flex-[1_0_0] gap-[var(--spacing\/1\,5,6px)] h-full items-center min-w-px overflow-clip relative">
      {event.valve ? (
        <ValveStatus state={event.valve} size={16} className="relative shrink-0 size-[16px]" title={`Valve ${event.valve}`} />
      ) : null}
    </div>
  )
}

function DetectedAtCell({ event }) {
  return (
    <div className="content-stretch flex flex-[1_0_0] h-full items-center min-w-px overflow-clip relative">
      <p className="[word-break:break-word] flex-[1_0_0] font-normal leading-[var(--text\/xs\/lh-snug,16.5px)] min-w-px overflow-hidden relative text-[12px] text-[color:var(--colors\/slate\/500,#62748e)] text-ellipsis whitespace-nowrap">
        {event.detectedAt}
      </p>
    </div>
  )
}

function NotifiedCell({ event }) {
  return (
    <div className="content-stretch flex flex-[1_0_0] h-full items-center justify-end min-w-px overflow-clip relative">
      <div className="bg-[var(--colors\/slate\/100,#f1f5f9)] content-stretch flex items-center justify-center relative rounded-[var(--rounded-full,9999px)] shrink-0 size-[24px]">
        <div className="[word-break:break-word] flex flex-col font-normal justify-center leading-[0] relative shrink-0 text-[color:var(--colors\/slate\/500,#62748e)] text-[length:var(--text\/sm\/size,12px)] text-center whitespace-nowrap">
          <p className="leading-[var(--text\/sm\/lh,19.5px)]">{event.notifiedBy}</p>
        </div>
      </div>
    </div>
  )
}

/** One data row: five cells under the shared grid, preceded by its rule.
 *  Rows carry no hover, no chevron and no destination on either Figma node, so
 *  they are deliberately inert — presentation only, no row click handler. */
function EventRow({ event }) {
  return (
    <Fragment>
      <Separator className="bg-[var(--colors\/slate\/200,#e2e8f0)] col-span-5 h-px justify-self-stretch relative shrink-0" />
      <div className="content-stretch flex gap-[var(--spacing\/2,8px)] items-center justify-self-stretch min-h-[48px] overflow-clip p-[var(--component\/data-table\/cell\/padding,12px)] relative self-stretch shrink-0" data-slot="table-cell">
        <SystemCell event={event} />
      </div>
      <div className="border-0 border-[var(--border,#e5e5e5)] border-solid content-stretch flex gap-[var(--spacing\/2,8px)] items-center justify-self-stretch min-h-[48px] overflow-clip px-[var(--component\/table\/cell\/padding,12px)] py-[var(--spacing\/1\,5,6px)] relative self-stretch shrink-0" data-slot="table-cell">
        <TypeCell event={event} />
      </div>
      <div className="border-0 border-[var(--border,#e5e5e5)] border-solid content-stretch flex gap-[var(--spacing\/2,8px)] items-center justify-self-stretch min-h-[48px] overflow-clip px-[var(--component\/table\/cell\/padding,12px)] py-[var(--spacing\/1\,5,6px)] relative self-stretch shrink-0" data-slot="table-cell">
        <ValveCell event={event} />
      </div>
      <div className="border-0 border-[var(--border,#e5e5e5)] border-solid content-stretch flex gap-[var(--spacing\/2,8px)] items-center justify-self-stretch min-h-[48px] overflow-clip px-[var(--component\/table\/cell\/padding,12px)] py-[var(--spacing\/1\,5,6px)] relative self-stretch shrink-0" data-slot="table-cell">
        <DetectedAtCell event={event} />
      </div>
      <div className="border-0 border-[var(--border,#e5e5e5)] border-solid content-stretch flex gap-[var(--spacing\/2,8px)] items-center justify-self-stretch min-h-[48px] overflow-clip px-[var(--component\/table\/cell\/padding,12px)] py-[var(--spacing\/1\,5,6px)] relative self-stretch shrink-0" data-slot="table-cell">
        <NotifiedCell event={event} />
      </div>
    </Fragment>
  )
}

// ── Card ───────────────────────────────────────────────────────────────────

/**
 * @param events      rows to render. Each: { id, systemName, location, address,
 *                    type, valve, detectedAt, notifiedBy, ignored, resolved }.
 *                    `resolved` splits the Active and History toggles; pass
 *                    `[]` to force the empty state.
 * @param onShowAll   fired when the Active toggle is chosen. The design's only
 *                    affordance for "show me the whole active list" — neither
 *                    node carries a separate "show all" control.
 * @param onShowPast  fired when the History toggle is chosen. This is the
 *                    design's route to past events: it lives in the header
 *                    toggle, not as a link under the empty state.
 */
export default function ActiveWaterEventsCard({ events = MOCK_EVENTS, onShowAll, onShowPast, className }) {
  const [tab, setTab] = useState('active')

  const rows = events.filter((e) => (tab === 'history' ? e.resolved : !e.resolved))
  const isEmpty = rows.length === 0

  const handleTab = (value) => {
    // Radix single-select emits '' when the pressed item is pressed again;
    // this switch has no "neither" state.
    if (!value) return
    setTab(value)
    if (value === 'history') onShowPast?.()
    else onShowAll?.()
  }

  return (
    <Card
      // Figma root, verbatim, minus two things: w-[760px] becomes a max-width
      // so the card survives a 375px shell, and the shadow class is dropped
      // because every one of its var() fallbacks resolved to 0/transparent —
      // Figma failed to resolve the "Liquid" effect, and the rendered node
      // plainly has a shadow. The Card primitive's own shadow stands instead.
      // gap-0 / p-0 neutralise the primitive's mobile padding; both are the
      // design's own values.
      className={
        'bg-[#fafbfc] border border-solid border-white content-stretch flex flex-col gap-0 h-[380px] items-start overflow-clip p-[var(--p-0,0px)] relative rounded-[var(--rounded-2xl,18px)] w-full max-w-[760px] ' +
        (className || '')
      }
    >
      {/* Header — identical in both variants apart from the dot's tint. */}
      <div className="content-stretch flex flex-col h-[62px] items-start justify-center px-[var(--spacing\/6,24px)] py-[var(--spacing\/3,12px)] relative shrink-0 w-full">
        <div className="content-stretch flex items-center justify-between relative shrink-0 w-full">
          <div className="content-stretch flex gap-[10px] items-center justify-center relative shrink-0">
            <LocationDot
              className="relative shrink-0 size-[27px]"
              style={{ color: isEmpty ? SLATE_INK : '#FB2C36' }}
            />
            <p className="[word-break:break-word] font-semibold leading-[var(--text\/lg\/lh-none,18px)] relative shrink-0 text-[color:var(--colors\/slate\/800,#1d293d)] text-[length:var(--text\/lg\/size,18px)] tracking-[-0.45px] whitespace-nowrap">
              Water Events
            </p>
          </div>

          {/* Figma ToggleGroup 198453:43614. The group clips to its own 34px
              pill, which is what gives the selected toggle a rounded outer
              edge and a square inner one. */}
          <ToggleGroup
            type="single"
            value={tab}
            onValueChange={handleTab}
            aria-label="Water events scope"
            className="bg-[var(--colors\/slate\/100,#f1f5f9)] content-stretch flex gap-[var(--p-0,0px)] items-center overflow-hidden p-[var(--p-0,0px)] relative rounded-[34px] shrink-0"
          >
            <ToggleGroupItem
              value="active"
              aria-label="Active water events"
              className="bg-transparent border border-solid border-transparent content-stretch cursor-pointer flex font-medium gap-[var(--component\/toggle\/gap,4px)] h-[36px] items-center justify-center leading-[var(--text\/sm-tight\/lh,20px)] min-h-[36px] overflow-clip px-[var(--component\/toggle\/size-default\/padding,12px)] py-[var(--p-0,0px)] relative shrink-0 text-[color:var(--foreground,#0a0a0a)] text-[length:var(--text\/sm-tight\/size,14px)] whitespace-nowrap hover:bg-transparent hover:text-[color:var(--wint-blue-accent,#0b81f8)] data-[state=on]:bg-transparent data-[state=on]:border-[var(--wint-blue-accent,#0b81f8)] data-[state=on]:rounded-bl-[var(--component\/toggle\/radius,26px)] data-[state=on]:rounded-tl-[var(--component\/toggle\/radius,26px)] data-[state=on]:text-[color:var(--wint-blue-accent,#0b81f8)]"
            >
              Active
            </ToggleGroupItem>
            <ToggleGroupItem
              value="history"
              aria-label="Past water events"
              className="bg-transparent border border-solid border-transparent content-stretch cursor-pointer flex font-medium gap-[var(--component\/toggle\/gap,4px)] h-[36px] items-center justify-center leading-[var(--text\/sm-tight\/lh,20px)] min-h-[36px] overflow-clip px-[var(--component\/toggle\/size-default\/padding,12px)] py-[var(--p-0,0px)] relative shrink-0 text-[color:var(--foreground,#0a0a0a)] text-[length:var(--text\/sm-tight\/size,14px)] whitespace-nowrap hover:bg-transparent hover:text-[color:var(--wint-blue-accent,#0b81f8)] data-[state=on]:bg-transparent data-[state=on]:border-[var(--wint-blue-accent,#0b81f8)] data-[state=on]:rounded-br-[var(--component\/toggle\/radius,26px)] data-[state=on]:rounded-tr-[var(--component\/toggle\/radius,26px)] data-[state=on]:text-[color:var(--wint-blue-accent,#0b81f8)]"
            >
              History
            </ToggleGroupItem>
          </ToggleGroup>
        </div>
      </div>

      {isEmpty ? (
        /* ── Property 1=empty (198209:67182) ───────────────────────────── */
        <div className="content-stretch flex flex-[1_0_0] flex-col gap-[var(--pro\/space\/4,16px)] items-center justify-center min-h-px relative w-full">
          <div className="h-[74px] relative shrink-0 w-[144px]">
            {/* Figma crops a 144x108 render down to a 74px band; the negative
                offset is the crop, not a nudge. Keep both numbers. */}
            <div className="absolute inset-0 overflow-hidden pointer-events-none">
              <img
                alt=""
                className="absolute h-[145.95%] left-0 max-w-none top-[-22.97%] w-full"
                src={EMPTY_ILLUSTRATION}
              />
            </div>
          </div>
          <div className="content-stretch flex flex-col gap-[var(--pro\/space\/2,8px)] items-center justify-center relative shrink-0 w-full">
            <div className="[word-break:break-word] content-stretch flex flex-col gap-[4px] items-center justify-center relative shrink-0 text-center w-full">
              <p className="font-semibold leading-[var(--text\/lg\/lh-none,18px)] relative shrink-0 text-[color:var(--colors\/slate\/800,#1d293d)] text-[length:var(--text\/lg\/size,18px)] tracking-[-0.45px] w-full" dir="auto">
                {tab === 'history' ? 'No past water events' : 'No active water events'}
              </p>
              <div className="flex flex-col font-normal justify-center leading-[0] relative shrink-0 text-[color:var(--muted-foreground,#737373)] text-[length:var(--text\/sm\/size,14px)] w-full">
                <p className="leading-[var(--text\/sm\/lh,20px)]">Everything looks good!</p>
              </div>
            </div>
          </div>
        </div>
      ) : (
        /* ── Property 1=Default (198209:67180) ─────────────────────────── */
        /* Figma pins this region at h-[323px] inside a 380px card and clips the
           overflow, so the sixth row and the last 5px of the Notifications
           column are unreachable in the comp. Here it is a real scroller: same
           padding, same column widths, nothing lost off the edge. */
        <div
          className="content-stretch flex flex-col items-start overflow-auto pl-[var(--spacing\/3,12px)] pr-[var(--spacing\/5,20px)] relative w-full"
          style={{ flex: '1 1 0%', minHeight: 0 }}
        >
          <div className="content-stretch flex flex-col items-start relative shrink-0 w-full">
            <div
              className="grid grid-cols-[336px_57px_61px_175px_104px] min-w-[733px] overflow-clip relative shrink-0 w-full"
              data-slot="table"
            >
              {/* Head */}
              <div className="border-0 border-[var(--border,#e5e5e5)] border-solid content-stretch flex gap-[var(--p-0,0px)] h-[48px] items-center justify-self-stretch pl-[12px] pr-[11px] py-[var(--p-0,0px)] relative shrink-0">
                <div className="content-stretch flex flex-[1_0_0] h-full items-center min-w-px relative">
                  <p className="[word-break:break-word] flex-[1_0_0] font-medium leading-[var(--text\/sm\/lh,20px)] min-w-px overflow-hidden relative text-[14px] text-[color:var(--colors\/slate\/700,#314158)] text-ellipsis whitespace-nowrap" dir="auto">
                    {'System & location'}
                  </p>
                </div>
              </div>
              {['Type', 'Valve', 'Detected at'].map((label) => (
                <div
                  key={label}
                  className="border-0 border-[var(--border,#e5e5e5)] border-solid content-stretch flex gap-[var(--p-0,0px)] h-[48px] items-center justify-self-stretch px-[var(--component\/data-table\/head\/px,12px)] py-[var(--p-0,0px)] relative shrink-0"
                >
                  <div className="content-stretch flex flex-[1_0_0] h-full items-center min-w-px relative">
                    <p className="[word-break:break-word] flex-[1_0_0] font-medium leading-[var(--text\/sm\/lh,20px)] min-w-px overflow-hidden relative text-[14px] text-[color:var(--colors\/slate\/700,#314158)] text-ellipsis whitespace-nowrap">
                      {label}
                    </p>
                  </div>
                </div>
              ))}
              <div className="border-0 border-[var(--border,#e5e5e5)] border-solid content-stretch flex gap-[var(--p-0,0px)] h-[48px] items-center justify-self-stretch px-[var(--component\/data-table\/head\/px,12px)] py-[var(--p-0,0px)] relative shrink-0">
                <div className="content-stretch flex flex-[1_0_0] h-full items-center min-w-px relative">
                  <p className="[word-break:break-word] flex-[1_0_0] font-medium leading-[var(--text\/sm\/lh,20px)] min-w-px overflow-hidden relative text-[14px] text-[color:var(--colors\/slate\/700,#314158)] text-ellipsis text-right whitespace-nowrap">
                    Notifications
                  </p>
                </div>
              </div>

              {/* Body — Figma draws a rule above every data row, including the
                  first: six rules for six rows. */}
              {rows.map((event) => (
                <EventRow key={event.id} event={event} />
              ))}
            </div>
          </div>
        </div>
      )}
    </Card>
  )
}
